contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        string memory name_,
        string memory tokenURI,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance,
        uint256 transferAmount
    ) public payable {
        require(itemsRemaining > 0);
        require(transferAmount > 0);
        require(transferAmount <= itemsRemaining);

        c.createGameItem(
            name_,
            tokenURI,
            true,
            true,
            itemsRemaining,
            itemPrice,
            dailyAllowance
        ); if (__ESBMC_reverted()) return;

        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        uint256 remainingBefore = c.remainingSupply(tokenId); if (__ESBMC_reverted()) return;

        bool reverted;
        c.safeTransferFrom(address(this), address(0xdead), tokenId, transferAmount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || remainingBefore == itemsRemaining || c.balanceOf(address(0xdead), tokenId) == transferAmount);
    }

    receive() external payable {}
}

